home=f'''<main id="main"><section class="hero wrap"><div class="hero-copy"><p class="eyebrow">APPLIED AI / SOFTWARE / ENTERPRISE SYSTEMS</p><h1>Intelligence,<br>engineered for<br><em>the real world.</em></h1><p class="lead">Turn complex business problems into intelligent, dependable systems. From the first useful AI workflow to the software that keeps it running.</p><div class="actions"><a class="button primary" href="#contact">Discuss your project <span aria-hidden="true">↗</span></a><a class="text-link" href="/labs/">Explore the lab <span aria-hidden="true">→</span></a></div><p class="hero-note">Independent engineering. Built for international teams.</p></div>{diagram}</section><div class="principles"><div class="wrap"><span>Practical intelligence</span><span>Clear architecture</span><span>Human oversight</span><span>Verifiable delivery</span></div></div>
<section class="section wrap" id="capabilities"><div class="section-intro"><p class="eyebrow">01 / CAPABILITIES</p><h2>From a promising idea<br>to a working system.</h2><p>Three connected disciplines. One focus: software that earns its place in your operations.</p></div><div class="service-list"><article class="service"><span class="number">01</span><div><h3>AI &amp; Machine Learning Engineering</h3><p>Put models to work with the context, tools and checks they need. Build toward useful decisions, not impressive-looking output.</p><ul class="tags"><li>Agents &amp; tool use</li><li>RAG &amp; knowledge systems</li><li>Predictive ML</li><li>Evaluation</li></ul></div><span class="service-symbol" aria-hidden="true">✳</span></article><article class="service"><span class="number">02</span><div><h3>Software &amp; Systems Engineering</h3><p>Design and deliver the applications behind the intelligence. Clear interfaces, reliable data flows and secure foundations that can evolve.</p><ul class="tags"><li>Full-stack applications</li><li>APIs &amp; integrations</li><li>Data architecture</li><li>Testing &amp; delivery</li></ul></div><span class="service-symbol" aria-hidden="true">⌘</span></article><article class="service"><span class="number">03</span><div><h3>Enterprise Automation &amp; Modernization</h3><p>Connect fragmented processes and reduce manual handoffs. Bring practical automation into existing enterprise systems, with people in control.</p><ul class="tags"><li>Workflow orchestration</li><li>System modernization</li><li>Power Platform</li><li>Dynamics &amp; Dataverse</li></ul></div><span class="service-symbol" aria-hidden="true">↗</span></article></div></section>
<section class="lab-feature"><div class="wrap lab-grid"><div><p class="eyebrow">02 / WORKING IN THE OPEN</p><h2>Inspect the workflow.<br>Question every step.</h2><p>Follow a synthetic enterprise request from intake to a human decision. See the extracted fields, classification rules, mock API lookup and record state as they change.</p><a class="button light" href="/labs/">Open the request workflow <span aria-hidden="true">↗</span></a><p class="fineprint">Interactive deterministic simulation. Synthetic data. No live AI or external messages.</p></div><div class="mini-flow" aria-label="Demo workflow overview"><span>REQUEST RECEIVED</span><i aria-hidden="true">↓</i><span>EXTRACT → CLASSIFY → LOOKUP</span><i aria-hidden="true">↓</i><span>DRAFT RECORD + ASSIGN OWNER</span><i aria-hidden="true">↓</i><strong>HUMAN VALIDATION</strong></div></div></section>
<section class="section wrap approach"><div><p class="eyebrow">03 / HOW WE WORK</p><h2>Make it concrete.<br>Then make it dependable.</h2></div><ol><li><strong>Frame the problem</strong><p>Clarify the users, data, operational constraints and what success would actually look like.</p></li><li><strong>Build a useful slice</strong><p>Connect a narrow, working flow. Inspect behavior with representative data and explicit failure paths.</p></li><li><strong>Verify and hand over</strong><p>Test the system, document its limits and leave a repeatable path for deployment and iteration.</p></li></ol></section>
<section class="contact wrap" id="contact"><div><p class="eyebrow">LET'S BUILD SOMETHING USEFUL</p><h2>Bring the problem.<br>Let's work through it.</h2><p>Describe the workflow, the systems involved and the outcome you need.</p></div><div><a class="button primary" href="https://github.com/Blaister9/santensor.github.io/issues/new?title=Project%20inquiry">Start a conversation on GitHub <span aria-hidden="true">↗</span></a><p class="fineprint">Opens a public GitHub issue and requires a GitHub account. Share only a high-level brief. Never include credentials or confidential information.</p></div></section></main>'''
write('index.html',page('Santensor — Applied AI & Software Engineering','Practical AI, dependable software and enterprise automation. Engineering intelligent systems for international teams.','/',home))
labs='''<main id="main" class="wrap"><section class="page-heading"><p class="eyebrow">SANTENSOR / LABS / 001</p><h1>From request<br>to reviewed result.</h1><p class="lead">An inspectable enterprise workflow, one real state transition at a time.</p><div class="notice"><strong>DETERMINISTIC SIMULATION — NO LIVE AI</strong><p>All records are synthetic. Extraction and classification use local rules; the enterprise API is a mock directory. Nothing is transmitted, emailed or created in another system. This demonstrates orchestration and human controls.</p></div></section><section class="demo-grid" aria-label="Interactive synthetic workflow"><div class="demo-input"><h2>1. Choose a request</h2><label for="fixture">Synthetic scenario</label><select id="fixture"><option value="standard">Account request · known account</option><option value="urgent">Urgent incident · known account</option><option value="unknown">Unknown account · safety checkpoint</option></select><label for="request">Request text (synthetic only)</label><textarea id="request" rows="6" maxlength="1500"></textarea><button id="reset" class="button secondary">Load / reset request</button><p class="fineprint">After editing, load the request to restart. Local page memory only; reload clears all state.</p><h2>2. Inspect the stages</h2><ol id="stage-list" class="stages"></ol></div><div class="demo-output"><div class="demo-bar"><span class="eyebrow">WORKFLOW INSPECTOR</span><span class="badge">MOCK API</span></div><p id="result" role="status" aria-live="polite"></p><pre id="workflow-state" tabindex="0" aria-label="Current structured workflow state"></pre><div class="demo-actions"><button id="step" class="button primary">Run next step →</button><button id="approve" class="button secondary">Approve draft</button><button id="reject" class="button secondary">Reject draft</button></div><p id="error" role="alert"></p><h3>Execution log</h3><ol id="event-log" class="event-log"></ol></div></section><section class="section architecture"><p class="eyebrow">UNDER THE SURFACE</p><h2>What runs. What is mocked.</h2><div class="architecture-grid"><article><h3>Runs in your browser</h3><p>A tested state machine. Pattern-based field extraction. Explicit incident rules. In-memory record creation, owner assignment and notification drafts. Approval cannot skip the human checkpoint.</p></article><article><h3>Clearly mocked</h3><p>The enterprise lookup uses a fixed fictional directory. No model inference, CRM write, email delivery or production performance claim. Unknown accounts cannot be approved.</p></article><article><h3>Path to a live integration</h3><p>Replace the local adapter with an authenticated server API, schema-validated model outputs and scoped tools. Add durable audit records, access controls, rate limits and spend limits before external actions.</p></article></div><a class="text-link" href="https://github.com/Blaister9/santensor.github.io/blob/feat/santensor-commercial-20261015/js/workflow.mjs">Inspect the public state machine ↗</a></section></main>'''
write('labs/index.html',page('Labs — Request Workflow | Santensor','Run an honest synthetic enterprise workflow with inspectable states, mock API lookup and explicit human review.','/labs/',labs,'<script type="module" src="/js/labs.mjs"></script>'))
cases='''<main id="main" class="wrap"><section class="page-heading"><p class="eyebrow">SANTENSOR / ENGINEERING NOTES</p><h1>Work you can inspect.<br>Claims you can trace.</h1><p class="lead">These are product experiments and lab builds, not client testimonials. No customer names, delivery metrics or commercial outcomes are implied.</p></section><article class="case"><div><span class="badge">SYNTHETIC LAB BUILD</span><h2>Enterprise request workflow</h2><p><strong>The problem.</strong> Requests cross multiple systems and lose context. Automated actions need a visible path back to their inputs and an explicit human decision.</p><p><strong>The build.</strong> A browser-local state machine extracts fields, classifies a request, looks up a fictional account and creates a draft record. Known accounts can be validated; unknown accounts require rejection.</p><p><strong>Evidence and limits.</strong> The interactive lab exposes structured state and an execution log. Automated tests cover every transition, input bounds and the approval guard. The API and data are mocked. No production savings are claimed.</p><a class="text-link" href="/labs/">Run the workflow →</a></div><div class="case-diagram" role="img" aria-label="Request to rules to mock API to draft to human decision"><span>SYNTHETIC REQUEST</span><b aria-hidden="true">↓</b><span>EXTRACTION + RULES</span><b aria-hidden="true">↓</b><span>MOCK DIRECTORY → DRAFT</span><b aria-hidden="true">↓</b><strong>HUMAN DECISION</strong></div></article><article class="case"><div><span class="badge">PRIVATE PRODUCT EXPERIMENT</span><h2>Technical interview coach</h2><p><strong>The problem.</strong> Software professionals need to explain technical decisions in English, using the requirements of an actual job description.</p><p><strong>The build.</strong> Recovery of an existing Next.js prototype, with private access, PostgreSQL session budgets, optional content persistence and a written rehearsal mode. Voice uses a server-mediated WebRTC design.</p><p><strong>Evidence and limits.</strong> Source, build and database tests are maintained privately. Written rehearsal is deterministic and produces no fluency scores. A bounded real OpenAI WebRTC session with synthetic desktop audio was verified. Physical Samsung device acceptance and human listening remain pending; no training effectiveness is claimed.</p></div><div class="case-diagram" role="img" aria-label="Job context to private practice to consented history"><span>JOB CONTEXT</span><b aria-hidden="true">↓</b><span>PRIVATE PRACTICE</span><b aria-hidden="true">↓</b><span>TRANSCRIPT EVIDENCE</span><b aria-hidden="true">↓</b><strong>OPTIONAL PRIVATE HISTORY</strong></div></article></main>'''
write('cases/index.html',page('Cases & Engineering Notes | Santensor','Inspectable lab builds and product experiments, with evidence and limitations clearly stated.','/cases/',cases))
privacy='''<main id="main" class="wrap prose page-heading"><p class="eyebrow">SANTENSOR / PRIVACY</p><h1>Small data footprint.<br>Clear boundaries.</h1><h2>This public website</h2><p>This static site uses no analytics, advertising cookies, tracking pixels or external fonts. Hosting providers may process access logs as part of delivering the site.</p><h2>The workflow lab</h2><p>The demo runs in page memory. It does not store requests in local storage or send them to an AI provider or enterprise API. Use only synthetic data. Reloading the page clears the simulation.</p><h2>Contact via GitHub</h2><p>The contact link opens a public issue in the existing Santensor website repository. A GitHub account is required; GitHub's terms and privacy policy apply. Share only a high-level project description. Do not post personal information, secrets or client-confidential material.</p><h2>Private interview coach</h2><p>The separate private application has its own authentication. Content persistence is optional. When voice is enabled, audio and job context are sent to OpenAI for processing; the app does not store recordings. Live voice verification is pending.</p><p>Last updated: October 16, 2026.</p></main>'''
write('privacy/index.html',page('Privacy | Santensor','Privacy boundaries for the static Santensor site, browser-local lab and public GitHub contact route.','/privacy/',privacy))
